contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        require(balAfter == balBefore + depositAmount, "deposit did not credit sender balance");
        require(cBalAfter == cBalBefore + depositAmount, "deposit did not increase contract balance");

        require(c.balances(address(this)) >= c.MinSum(), "balance below MinSum");
        require(collectAmount <= c.balances(address(this)), "collect amount exceeds balance");

        bool collectReverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        assert(
            (!collectReverted && c.balances(address(this)) == balAfter - collectAmount && address(c).balance == cBalAfter - collectAmount)
            ||
            (collectReverted && c.balances(address(this)) == balAfter && address(c).balance == cBalAfter)
        );
    }
}

